export const ACTION_04_PROMPT_VERSION = "1.0.0";

export interface Action04PromptInput {
  extractedIssues: Array<{
    id: string;
    title: string;
    description: string;
    category: string;
    reportedBy: string;
    reportedDate: string;
  }>;
  priorityRules: {
    importanceFactors: string[];
    urgencyFactors: string[];
    scoringMethod: string;
  };
  historicalContext?: Array<{
    issueId: string;
    previousPriority: number;
    resolutionTime: number;
    recurrenceCount: number;
  }>;
}

export interface Action04PromptOutput {
  systemPrompt: string;
  userPrompt: string;
  metadata: {
    version: string;
    actionNumber: 4;
    purpose: string;
    expectedOutputFormat: string;
  };
}

export function buildAction04Prompt(
  input: Action04PromptInput
): Action04PromptOutput {
  const systemPrompt = `You are an AI agent responsible for prioritizing issues based on importance and urgency factors.

Your task is to analyze extracted issues and assign priority scores using the provided rules.

Priority Assignment Rules:
- Importance Factors: ${input.priorityRules.importanceFactors.join(", ")}
- Urgency Factors: ${input.priorityRules.urgencyFactors.join(", ")}
- Scoring Method: ${input.priorityRules.scoringMethod}

Output Format:
For each issue, provide:
1. Issue ID
2. Assigned Priority Score (1-10, where 10 is highest priority)
3. Priority Level (Critical/High/Medium/Low)
4. Justification (brief explanation of scoring)
5. Recommended Action Timeline

Consider historical context when available to identify recurring issues that may warrant higher priority.`;

  const historicalContextStr =
    input.historicalContext && input.historicalContext.length > 0
      ? `\n\nHistorical Context:\n${input.historicalContext
          .map(
            (ctx) =>
              `- Issue ${ctx.issueId}: Previous Priority ${ctx.previousPriority}, ` +
              `Resolution Time ${ctx.resolutionTime}h, Recurrence Count ${ctx.recurrenceCount}`
          )
          .join("\n")}`
      : "";

  const userPrompt = `Please prioritize the following extracted issues:

${input.extractedIssues
  .map(
    (issue, idx) =>
      `Issue ${idx + 1}:
  ID: ${issue.id}
  Title: ${issue.title}
  Description: ${issue.description}
  Category: ${issue.category}
  Reported By: ${issue.reportedBy}
  Reported Date: ${issue.reportedDate}`
  )
  .join("\n\n")}${historicalContextStr}

Analyze each issue and assign priority scores. Identify any recurring issues that require escalation.
Provide the prioritized list in descending order of priority score.`;

  return {
    systemPrompt,
    userPrompt,
    metadata: {
      version: ACTION_04_PROMPT_VERSION,
      actionNumber: 4,
      purpose:
        "Assign priority scores to extracted issues based on importance and urgency factors",
      expectedOutputFormat:
        "JSON array with issue IDs, priority scores, priority levels, justifications, and recommended action timelines",
    },
  };
}
